// Replays trace.json (generated by `node packages/cli/dist/index.js trace`). The page never
// computes run state itself: every node state shown here was produced by the core reducer.

const NODE_WIDTH = 236;
const NODE_HEIGHT = 104;
const COLUMN_GAP = 104;
const ROW_GAP = 34;
const MARGIN = 24;
const MIN_BOARD_COLUMNS = 3;
const SVG_NS = "http://www.w3.org/2000/svg";
const PLAY_INTERVAL_MS = 1400;

const view = { trace: null, scenario: null, step: 0, timer: null };

const byId = (id) => document.getElementById(id);

function svg(tag, attributes = {}, text) {
  const element = document.createElementNS(SVG_NS, tag);
  for (const [name, value] of Object.entries(attributes)) element.setAttribute(name, String(value));
  if (text !== undefined) element.textContent = text;
  return element;
}

function html(tag, attributes = {}, text) {
  const element = document.createElement(tag);
  for (const [name, value] of Object.entries(attributes)) element.setAttribute(name, String(value));
  if (text !== undefined) element.textContent = text;
  return element;
}

/** Lamp class for a node: execution progress and result trust folded into one signal. */
function lampState(node) {
  if (node.execution === "cancelled") return "s-cancelled";
  if (node.execution === "failed" || node.execution === "exhausted" || node.disposition === "rejected") {
    return "s-failed";
  }
  if (node.disposition === "accepted") return "s-accepted";
  if (node.execution === "result_ready") return "s-unverified";
  if (node.execution === "running") return "s-running";
  if (node.execution === "ready") return "s-ready";
  return "s-pending";
}

function describeNode(node) {
  const parts = [node.execution.replace("_", " ")];
  if (node.disposition !== null) parts.push(node.disposition);
  return parts.join(", ");
}

/** Columns by longest path from a root, rows by declaration order. */
function layout(graph) {
  const column = new Map(graph.nodes.map((node) => [node.id, 0]));
  let changed = true;
  while (changed) {
    changed = false;
    for (const edge of graph.edges) {
      const next = column.get(edge.from) + 1;
      if (next > column.get(edge.to)) {
        column.set(edge.to, next);
        changed = true;
      }
    }
  }
  const rows = new Map();
  const positions = new Map();
  for (const node of graph.nodes) {
    const col = column.get(node.id);
    const row = rows.get(col) ?? 0;
    rows.set(col, row + 1);
    positions.set(node.id, {
      x: MARGIN + col * (NODE_WIDTH + COLUMN_GAP),
      y: MARGIN + row * (NODE_HEIGHT + ROW_GAP),
    });
  }
  // Lay every graph out on a board at least three columns wide so all scenarios render at
  // the same scale, and centre narrower graphs on it.
  const columns = Math.max(...column.values()) + 1;
  const maxRows = Math.max(...rows.values());
  const boardColumns = Math.max(columns, MIN_BOARD_COLUMNS);
  const offset = ((boardColumns - columns) * (NODE_WIDTH + COLUMN_GAP)) / 2;
  for (const position of positions.values()) position.x += offset;
  return {
    positions,
    width: MARGIN * 2 + boardColumns * NODE_WIDTH + (boardColumns - 1) * COLUMN_GAP,
    height: MARGIN * 2 + maxRows * NODE_HEIGHT + (maxRows - 1) * ROW_GAP,
  };
}

function renderGraph(scenario, step, previous) {
  const graph = scenario.graph;
  const { positions, width, height } = layout(graph);
  const root = byId("graph");
  root.replaceChildren();
  root.setAttribute("viewBox", `0 0 ${width} ${height}`);

  const defs = svg("defs");
  const marker = svg("marker", {
    id: "arrow",
    viewBox: "0 0 10 10",
    refX: 9,
    refY: 5,
    markerWidth: 7,
    markerHeight: 7,
    orient: "auto-start-reverse",
  });
  marker.append(svg("path", { d: "M 0 0 L 10 5 L 0 10 z", fill: "currentColor", class: "edge-arrow" }));
  defs.append(marker);
  root.append(defs);

  for (const edge of graph.edges) {
    const from = positions.get(edge.from);
    const to = positions.get(edge.to);
    const x1 = from.x + NODE_WIDTH;
    const y1 = from.y + NODE_HEIGHT / 2;
    const x2 = to.x - 4;
    const y2 = to.y + NODE_HEIGHT / 2;
    const bend = (x2 - x1) / 2;
    const path = svg("path", {
      d: `M ${x1} ${y1} C ${x1 + bend} ${y1}, ${x2 - bend} ${y2}, ${x2} ${y2}`,
      class: `edge ${edge.condition === "result_ready" ? "result-ready" : "accepted"}`,
      "marker-end": "url(#arrow)",
      style: "color: var(--ink-soft)",
    });
    const label = svg(
      "text",
      // Label the edge where it leaves its source: above a level or falling edge, below a rising one.
      { x: x1 + 10, y: y2 < y1 ? y1 + 20 : y1 - 9, "text-anchor": "start", class: "edge-label" },
      edge.condition === "result_ready" ? "result" : "accepted",
    );
    root.append(path, label);
  }

  for (const spec of graph.nodes) {
    const node = step.nodes[spec.id];
    const before = previous?.nodes[spec.id];
    const changed = before !== undefined && JSON.stringify(before) !== JSON.stringify(node);
    const { x, y } = positions.get(spec.id);
    const group = svg("g", { class: `node${changed ? " changed" : ""}`, transform: `translate(${x} ${y})` });
    group.append(
      svg("rect", { width: NODE_WIDTH, height: NODE_HEIGHT, rx: 10, class: "node-box" }),
      svg("circle", { cx: 30, cy: 34, r: 13, class: `node-lamp ${lampState(node)}` }),
      svg("text", { x: 54, y: 42, class: "node-name" }, spec.id),
      svg("text", { x: 20, y: 72, class: "node-detail" }, describeNode(node)),
    );
    const attempts = node.attemptCount === 1 ? "1 attempt" : `${node.attemptCount} attempts`;
    group.append(svg("text", { x: 20, y: 92, class: "node-detail" }, `${spec.role}, ${attempts}`));
    group.append(svg("title", {}, `${spec.id}: ${spec.objective}`));
    root.append(group);
  }
}

function renderStepPanel(scenario, step) {
  byId("step-count").textContent = `Step ${step.index + 1} of ${scenario.steps.length}`;
  byId("step-note").textContent = step.note;

  const outcome = byId("outcome");
  outcome.replaceChildren();
  if (step.outcome === "applied") {
    outcome.className = "outcome";
    outcome.textContent = "Applied";
  } else {
    outcome.className = "outcome rejected";
    outcome.textContent = `Rejected: ${step.rejection.code}`;
    outcome.append(html("span", { class: "reason" }, step.rejection.message));
  }

  byId("event-json").textContent = JSON.stringify(step.event, null, 2);

  const commands = byId("commands");
  commands.replaceChildren();
  if (step.commands.length === 0) {
    commands.append(html("p", { class: "none" }, "None"));
  }
  for (const command of step.commands) {
    const { type, ...rest } = command;
    const detail = Object.entries(rest)
      .map(
        ([key, value]) =>
          `${key}: ${typeof value === "string" && value.length > 24 ? `${value.slice(0, 19)}…` : value}`,
      )
      .join(", ");
    commands.append(html("p", { class: `command ${type.replace("_", "-")}` }, `${type}  ${detail}`));
  }

  const run = byId("run-status");
  run.replaceChildren();
  const status = html("span", {}, "Run ");
  status.append(html("span", { class: `value status-${step.run.status}` }, step.run.status.replace("_", " ")));
  run.append(status, html("span", {}, `Permits in use: ${step.run.permitsInUse}/${scenario.policy.maxConcurrent}`));
}

function renderTape(scenario) {
  const tape = byId("tape");
  tape.replaceChildren();
  for (const step of scenario.steps) {
    const classes = [];
    if (step.outcome === "rejected") classes.push("rejected");
    if (step.index > view.step) classes.push("future");
    const button = html("button", { type: "button", class: classes.join(" ") });
    if (step.index === view.step) button.setAttribute("aria-current", "step");
    button.append(html("span", {}, `${step.index + 1}`));
    button.append(html("span", { class: "tape-type" }, step.event.type));
    button.addEventListener("click", () => go(scenario.id, step.index));
    const item = html("li");
    item.append(button);
    tape.append(item);
  }
  // Scroll the tape itself, never the page, so the current step stays visible.
  const current = tape.querySelector('[aria-current="step"]');
  if (current !== null) {
    const item = current.parentElement;
    const left = item.offsetLeft - tape.offsetLeft;
    if (left < tape.scrollLeft || left + item.offsetWidth > tape.scrollLeft + tape.clientWidth) {
      tape.scrollLeft = left - (tape.clientWidth - item.offsetWidth) / 2;
    }
  }
}

function renderTabs() {
  const tabs = byId("scenario-tabs");
  tabs.replaceChildren();
  tabs.setAttribute("role", "tablist");
  for (const scenario of view.trace.scenarios) {
    const selected = scenario.id === view.scenario.id;
    const button = html("button", { type: "button", role: "tab", "aria-selected": selected }, scenario.title);
    button.addEventListener("click", () => go(scenario.id, 0));
    tabs.append(button);
  }
}

function render() {
  const scenario = view.scenario;
  const step = scenario.steps[view.step];
  renderTabs();
  byId("scenario-summary").textContent = scenario.summary;
  renderGraph(scenario, step, scenario.steps[view.step - 1]);
  renderStepPanel(scenario, step);
  renderTape(scenario);
  byId("prev").disabled = view.step === 0;
  byId("next").disabled = view.step === scenario.steps.length - 1;
  const replay = scenario.replayMatches ? "matches" : "does not match";
  byId("provenance").textContent =
    `Final status: ${scenario.finalStatus}. Replaying the applied events from scratch ${replay} the live state.`;
}

function go(scenarioId, stepIndex) {
  const scenario = view.trace.scenarios.find((candidate) => candidate.id === scenarioId) ?? view.trace.scenarios[0];
  view.scenario = scenario;
  view.step = Math.min(Math.max(stepIndex, 0), scenario.steps.length - 1);
  const hash = `#${scenario.id}/${view.step + 1}`;
  if (location.hash !== hash) history.replaceState(null, "", hash);
  render();
}

function stopPlaying() {
  if (view.timer !== null) clearInterval(view.timer);
  view.timer = null;
  byId("play").textContent = "Play";
}

function togglePlay() {
  if (view.timer !== null) {
    stopPlaying();
    return;
  }
  if (view.step === view.scenario.steps.length - 1) go(view.scenario.id, 0);
  byId("play").textContent = "Pause";
  view.timer = setInterval(() => {
    if (view.step >= view.scenario.steps.length - 1) {
      stopPlaying();
      return;
    }
    go(view.scenario.id, view.step + 1);
  }, PLAY_INTERVAL_MS);
}

function fromHash() {
  const [id, step] = location.hash.slice(1).split("/");
  return { id, step: Number.parseInt(step ?? "1", 10) - 1 || 0 };
}

async function main() {
  try {
    const response = await fetch("trace.json");
    if (!response.ok) throw new Error(`trace.json returned HTTP ${response.status}`);
    view.trace = await response.json();
  } catch (error) {
    const message = html(
      "p",
      { class: "load-error" },
      `Could not load trace.json (${error.message}). Run "npm run site" and serve the site/ directory over HTTP.`,
    );
    document.querySelector("main").replaceChildren(message);
    return;
  }

  byId("prev").addEventListener("click", () => {
    stopPlaying();
    go(view.scenario.id, view.step - 1);
  });
  byId("next").addEventListener("click", () => {
    stopPlaying();
    go(view.scenario.id, view.step + 1);
  });
  byId("play").addEventListener("click", togglePlay);
  document.addEventListener("keydown", (event) => {
    if (event.target instanceof HTMLElement && event.target.closest("input, textarea")) return;
    if (event.key === "ArrowRight") go(view.scenario.id, view.step + 1);
    if (event.key === "ArrowLeft") go(view.scenario.id, view.step - 1);
  });

  const initial = fromHash();
  go(initial.id, initial.step);
}

main();
